Ui.Script:

NUM_ALWAYS_UP_ROWS = 0;

-- The reference's own numbers (worldstate-ui-law.md §12). The row is an anchor node, not a
-- box: its 42-wide icon slot hangs off its left edge and its text runs past its right, so
-- none of these are "the readout's size" — they are the offsets that seat corner-authored
-- art against a label. The pitch is the template height, because rows chain TOP to the
-- previous row's BOTTOM with no gap.
WORLD_STATE_ROW_HEIGHT = 24;
-- The dynamic-icon flash: 0.5 s in, 0.5 s out, indefinitely.
WORLD_STATE_FLASH_HALF = 0.5;

-- The flash overlay's ramp. The art (…Flash.blp) is DXT1 with no alpha channel — black IS
-- the transparency — which is why it draws ADD; the pulse is the region's own alpha.
function WorldStateDynamicIcon_OnUpdate(elapsed)
    local t = (this.flashTime or 0) + elapsed;
    local period = 2 * WORLD_STATE_FLASH_HALF;
    while ( t >= period ) do
        t = t - period;
    end
    this.flashTime = t;
    local level = t / WORLD_STATE_FLASH_HALF;
    if ( level > 1 ) then
        level = 2 - level;
    end
    getglobal(this:GetName() .. "Flash"):SetAlpha(level);
end

-- Rebuild the readout from the host's list. Cheap enough to run whole on every fire: the
-- list is at most a handful of rows, and the events are a zone's worth apart.
function WorldStateAlwaysUpFrame_Update()
    local numUI = GetNumWorldStateUI();

    -- Grow the row pool on demand and never shrink it, the way every pooled list here
    -- does: the tail from a busier zone is parked hidden rather than destroyed. Row 1
    -- hangs off the container; every later row chains to the one above it, so the pitch is
    -- the template's height and lives in exactly one place.
    if ( numUI > NUM_ALWAYS_UP_ROWS ) then
        for i = NUM_ALWAYS_UP_ROWS + 1, numUI do
            local row = CreateFrame("Frame", "WorldStateAlwaysUpFrame" .. i,
                WorldStateAlwaysUpFrame, "WorldStateAlwaysUpTemplate");
            if ( i == 1 ) then
                row:SetPoint("TOP", WorldStateAlwaysUpFrame, "TOP", -23, -20);
            else
                row:SetPoint("TOP", getglobal("WorldStateAlwaysUpFrame" .. (i - 1)),
                    "BOTTOM", 0, 0);
            end
        end
        NUM_ALWAYS_UP_ROWS = numUI;
    end

    for i = 1, NUM_ALWAYS_UP_ROWS do
        local row = getglobal("WorldStateAlwaysUpFrame" .. i);
        if ( i > numUI ) then
            row:Hide();
        else
            local uiState, text, icon, dynamicIcon, tooltip, dynamicTooltip = GetWorldStateUIInfo(i);
            local name = row:GetName();

            -- The static slot takes its column verbatim. An EMPTY column is not a special
            -- case: SetTexture("") clears the art and draws nothing while the authored
            -- 42x42 rect — and so everything anchored to it — stays exactly where it was.
            -- The slot is reserved and blank, never collapsed; a row that slid its text
            -- left into the empty slot would ragged the readout's left edge, and the
            -- reference does no such thing.
            getglobal(name .. "Icon"):SetTexture(icon);
            getglobal(name .. "Text"):SetText(text);
            row.tooltip = tooltip;

            -- The dynamic slot is a SEPARATE button off the row's right edge, and it is
            -- the flag-taken state alone that shows it.
            local dynamic = getglobal(name .. "DynamicIcon");
            if ( dynamicIcon ~= "" and uiState == 2 ) then
                getglobal(dynamic:GetName() .. "Texture"):SetTexture(dynamicIcon);
                getglobal(dynamic:GetName() .. "Flash"):SetTexture(dynamicIcon .. "Flash");
                dynamic.tooltip = dynamicTooltip;
                dynamic.flashTime = 0;
                dynamic:Show();
            else
                dynamic:Hide();
            end
            row:Show();
        end
    end

    -- OURS, and non-visual: the reference's container is a bare 10x10 anchor node it never
    -- resizes, so its own bottom says nothing about how far the rows reach. We keep the
    -- authored size but grow the height to the rows' real extent, so "how much of the top
    -- of the screen is this using?" is a question the frame can answer — the dev cost pill
    -- asks it, and seats itself below (crates/benilla-app/src/perf/hud.rs). Rows anchor to
    -- the container's TOP, which is fixed, so nothing moves.
    if ( numUI > 0 ) then
        WorldStateAlwaysUpFrame:SetHeight(20 + numUI * WORLD_STATE_ROW_HEIGHT);
        WorldStateAlwaysUpFrame:Show();
    else
        WorldStateAlwaysUpFrame:Hide();
    end
end

function WorldStateAlwaysUpFrame_OnEvent()
    WorldStateAlwaysUpFrame_Update();
end

Scripts.OnEnter:
if ( this.tooltip and this.tooltip ~= "" ) then
    GameTooltip:SetOwner(this, "ANCHOR_BOTTOMLEFT");
    GameTooltip:SetText(this.tooltip);
    GameTooltip:Show();
end

if ( this.tooltip and this.tooltip ~= "" ) then
    GameTooltip:SetOwner(this, "ANCHOR_BOTTOMLEFT");
    GameTooltip:SetText(this.tooltip);
    GameTooltip:Show();
end

Scripts.OnLoad:
-- UPDATE_WORLD_STATES is the reference's own event for this list (0x20e). The
-- entering-world fire is what paints the readout on a login that lands inside a
-- scope the server has already sent states for.
this:RegisterEvent("UPDATE_WORLD_STATES");
this:RegisterEvent("PLAYER_ENTERING_WORLD");
